const string W="D:/project/MTGB/design-demos/battlefield-redesign-2026-10-24/";
var ui=UnityEngine.Object.FindFirstObjectByType<ForgeBattlefieldController>();var flags=System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance;
var results=new System.Collections.Generic.List<object>();int checks=0,failed=0;string savedLanguage=GamePreferences.Language;float savedScale=GamePreferences.TextScale;
void Check(bool pass,string context){checks++;if(!pass)failed++;results.Add(new{pass,context});}
void Save(string status){var method=Type.GetType("Newtonsoft.Json.JsonConvert, Newtonsoft.Json").GetMethod("SerializeObject",new[]{typeof(object)});System.IO.File.WriteAllText(W+"stack-reference-style-validation.json",(string)method.Invoke(null,new object[]{new{status,checks,failed,results}}));}
ForgeSeatView Sample()=>JsonUtility.FromJson<ForgeSeatView>(System.IO.File.ReadAllText(W+"native-full-seat.json"));
Transform Root()=>GameObject.Find("Canvas").transform;
string Ordinal(int n)=>(string)typeof(ForgeBattlefieldController).GetMethod("StackPositionLabel",flags).Invoke(ui,new object[]{n});
System.Collections.IEnumerator Settle(float duration=.18f){yield return new WaitForSecondsRealtime(duration);Canvas.ForceUpdateCanvases();}
Rect Bounds(RectTransform r){var c=new Vector3[4];r.GetWorldCorners(c);return Rect.MinMaxRect(c.Min(v=>v.x),c.Min(v=>v.y),c.Max(v=>v.x),c.Max(v=>v.y));}
bool Hollow(BattlefieldStackFrameGraphic frame){var helper=new UnityEngine.UI.VertexHelper();typeof(BattlefieldStackFrameGraphic).GetMethod("OnPopulateMesh",flags,null,new[]{typeof(UnityEngine.UI.VertexHelper)},null).Invoke(frame,new object[]{helper});var mesh=new Mesh();helper.FillMesh(mesh);helper.Dispose();var points=mesh.vertices;var triangles=mesh.triangles;Vector2 p=frame.rectTransform.rect.center;float Cross(Vector2 a,Vector2 b,Vector2 c)=>(b.x-a.x)*(c.y-a.y)-(b.y-a.y)*(c.x-a.x);bool filled=false;for(int i=0;i<triangles.Length;i+=3){Vector2 a=points[triangles[i]],b=points[triangles[i+1]],c=points[triangles[i+2]];float x=Cross(a,b,p),y=Cross(b,c,p),z=Cross(c,a,p);if(Mathf.Min(x,Mathf.Min(y,z))>=0||Mathf.Max(x,Mathf.Max(y,z))<=0){filled=true;break;}}UnityEngine.Object.Destroy(mesh);return !filled&&triangles.Length>0;}
bool Click(UnityEngine.UI.Button b){var p=new UnityEngine.EventSystems.PointerEventData(UnityEngine.EventSystems.EventSystem.current){position=Bounds((RectTransform)b.transform).center,button=UnityEngine.EventSystems.PointerEventData.InputButton.Left};var hits=new System.Collections.Generic.List<UnityEngine.EventSystems.RaycastResult>();UnityEngine.EventSystems.EventSystem.current.RaycastAll(p,hits);bool hit=hits.Count>0&&hits[0].gameObject.GetComponentInParent<UnityEngine.UI.Button>()==b;if(hit)UnityEngine.EventSystems.ExecuteEvents.ExecuteHierarchy(hits[0].gameObject,p,UnityEngine.EventSystems.ExecuteEvents.pointerClickHandler);else results.Add(new{button=b.name,blockedBy=hits.Take(3).Select(h=>h.gameObject.name).ToArray()});return hit;}
var assembly=typeof(UnityEditor.Editor).Assembly;var gameViewType=assembly.GetType("UnityEditor.GameView");var gameView=UnityEditor.EditorWindow.GetWindow(gameViewType);var sizeProperty=gameViewType.GetProperty("selectedSizeIndex",System.Reflection.BindingFlags.Public|System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance);int savedSize=(int)sizeProperty.GetValue(gameView);var sizesType=assembly.GetType("UnityEditor.GameViewSizes");var sizes=typeof(UnityEditor.ScriptableSingleton<>).MakeGenericType(sizesType).GetProperty("instance").GetValue(null);var group=sizesType.GetMethod("GetGroup").Invoke(sizes,new object[]{Enum.Parse(assembly.GetType("UnityEditor.GameViewSizeGroupType"),"Standalone")});var added=new System.Collections.Generic.List<int>();
void Resize(int w,int h){int index=((string[])group.GetType().GetMethod("GetDisplayTexts").Invoke(group,null)).Length;var size=Activator.CreateInstance(assembly.GetType("UnityEditor.GameViewSize"),new object[]{Enum.Parse(assembly.GetType("UnityEditor.GameViewSizeType"),"FixedResolution"),w,h,"MTGB stack reference style"});group.GetType().GetMethod("AddCustomSize").Invoke(group,new[]{size});added.Add(index);sizeProperty.SetValue(gameView,index);gameView.Repaint();}
void Restore(){sizeProperty.SetValue(gameView,savedSize);foreach(int i in added.OrderByDescending(i=>i))group.GetType().GetMethod("RemoveCustomSize").Invoke(group,new object[]{i});GamePreferences.SetLanguage(savedLanguage);GamePreferences.SetScale(savedScale);}
System.Collections.IEnumerator Run(){
 foreach(string language in new[]{"zh-CN","en-US","ja-JP"}){
  GamePreferences.SetLanguage(language);yield return null;while(!GamePreferences.Ready)yield return null;
  foreach(float scale in new[]{.85f,1f,1.3f}){
   GamePreferences.SetScale(scale);
   foreach(int count in new[]{0,1,2,12,30}){
    var v=Sample();var entries=v.stackItems;v.stackItems=Enumerable.Range(0,count).Select(i=>{var e=JsonUtility.FromJson<ForgeStackItem>(JsonUtility.ToJson(entries[i%entries.Length]));e.id=92000+i;if(e.targets!=null)foreach(var t in e.targets)if(t.kind=="stack")t.stackId=92001;return e;}).ToArray();v.stack=v.stackItems.Select(e=>e.description).ToArray();v.stackCount=count;
    ui.Present(null,1,false,null,null,"");yield return null;ui.Present(v,1,false,null,null,"");yield return Settle();string context=language+"/"+scale+"/"+count;var column=Root().Find("StackColumn") as RectTransform;Check(column.gameObject.activeSelf==(count>0),context+" visibility");if(count==0)continue;
    Check(column.rect.width==430&&column.anchoredPosition.y==-72,context+" larger and lower");Check(column.GetComponent<BattlefieldStackPanelTint>()!=null&&column.Find("CompactFrame").GetComponent<BattlefieldStackFrameGraphic>()!=null,context+" framed gradient panel");if(count==2)Check(Hollow(column.Find("CompactFrame").GetComponent<BattlefieldStackFrameGraphic>())&&Hollow(column.Find("Viewport/Content/StackEntry_1/CompactFrame").GetComponent<BattlefieldStackFrameGraphic>()),context+" border never fills center");
    var viewport=column.Find("Viewport") as RectTransform;var scroll=viewport.GetComponent<UnityEngine.UI.ScrollRect>();float limit=(float)typeof(ForgeBattlefieldController).GetProperty("RedesignStackMaximumHeight",flags).GetValue(ui);Check(Mathf.Abs(viewport.rect.height-Mathf.Min(limit,scroll.content.rect.height))<1,context+" fit without empty tail");
    for(int n=0;n<count;n++){
     var row=scroll.content.Find("StackEntry_"+n);var owner=row.Find("CompactOwner").GetComponent<UnityEngine.UI.Text>();Check(owner.text.Contains(Ordinal(n+1)),context+" own ordinal "+n);
     foreach(var label in row.GetComponentsInChildren<UnityEngine.UI.Text>(false).Where(t=>t.name.StartsWith("Compact")))Check(label.preferredHeight<=label.rectTransform.rect.height+2,context+" label fits "+n+"/"+label.name);
    }
    var title=scroll.content.Find("StackEntry_0/CompactTitle").GetComponent<UnityEngine.UI.Text>();Check(title.fontSize>=Mathf.RoundToInt(28*scale)-1&&title.GetComponent<PreferenceText>().KeepFont,context+" larger serif title");
    var heading=column.Find("Header").GetComponent<UnityEngine.UI.Text>();Check(heading.preferredHeight<=heading.rectTransform.rect.height+2,context+" heading fits");
    if(count>=12){scroll.verticalNormalizedPosition=0;yield return null;Check(scroll.content.anchoredPosition.y>=scroll.content.rect.height-viewport.rect.height-2,context+" scroll bottom");}
    if(count==2){var top=scroll.content.Find("StackEntry_0");var summary=top.Find("CompactNote").GetComponent<UnityEngine.UI.Text>().text;Check(summary.Contains(language=="zh-CN"?"反击":language=="en-US"?"Counter":"打ち消"),context+" summary is resolution effect");var targetText=top.Find("CompactTargets").GetComponent<UnityEngine.UI.Text>();Check(targetText.text.Contains(Ordinal(2)),context+" target ordinal after name");var incoming=scroll.content.Find("StackEntry_1/CompactIncoming_0").GetComponent<UnityEngine.UI.Text>();Check(incoming.text.Contains(Ordinal(1))&&incoming.color.r>incoming.color.b,context+" incoming source ordinal and enemy color");var frame=scroll.content.Find("StackEntry_1/CompactFrame").GetComponent<BattlefieldStackFrameGraphic>();Check(frame.enabled&&frame.Thickness<=1&&frame.color.a<.7f,context+" target has thin hollow frame");var collapse=column.Find("CollapseStack").GetComponent<UnityEngine.UI.Button>();Check(Click(collapse),context+" hide reachable over field");yield return Settle(.08f);Check(!viewport.gameObject.activeSelf&&column.rect.height==68,context+" hides rows and frame shrinks");Check(Click(collapse),context+" restore reachable");yield return Settle(.08f);Check(viewport.gameObject.activeSelf,context+" restore rows");}
   }
  }Save("RUNNING");
 }
 GamePreferences.SetLanguage("zh-CN");yield return null;while(!GamePreferences.Ready)yield return null;GamePreferences.SetScale(1);
 foreach(bool reverse in new[]{false,true}){
  var v=Sample();v.stackItems[0].source=JsonUtility.FromJson<ForgeCardView>(JsonUtility.ToJson(v.stackItems[1].source));if(reverse)Array.Reverse(v.stackItems);v.stack=v.stackItems.Select(e=>e.description).ToArray();ui.Present(null,1,false,null,null,"");yield return null;ui.Present(v,1,false,null,null,"");yield return Settle(.35f);
  int source=Array.FindIndex(v.stackItems,e=>(e.targets?.Length??0)>0);int target=1-source;var text=Root().Find("StackColumn/Viewport/Content/StackEntry_"+source+"/CompactTargets").GetComponent<UnityEngine.UI.Text>();Check(text.text.Contains(GamePreferences.CardFaceName(v.stackItems[target].source.name)+"（"+Ordinal(target+1)+"）"),"same-name identity after reordering "+reverse);
 }
 var absent=Sample();var gone=absent.stackItems[1];absent.stackItems[0].targets[0].card=gone.source;absent.stackItems=new[]{absent.stackItems[0]};absent.stack=new[]{absent.stack[0]};absent.stackCount=1;ui.Present(null,1,false,null,null,"");yield return null;ui.Present(absent,1,false,null,null,"");yield return Settle();Check(Root().Find("StackColumn/Viewport/Content/StackEntry_0/CompactTargets").GetComponent<UnityEngine.UI.Text>().text.Contains("已离开堆叠"),"departed target never invents ordinal");
 foreach(var size in new[]{new Vector2Int(1280,720),new Vector2Int(1920,1080),new Vector2Int(1024,768)}){
  Resize(size.x,size.y);yield return Settle(.3f);var v=Sample();ui.Present(null,1,false,null,null,"");yield return null;ui.Present(v,1,false,null,null,"");yield return Settle(.6f);var col=Root().Find("StackColumn") as RectTransform;var rect=Bounds(col);Check(Screen.width==size.x&&Screen.height==size.y&&rect.xMin>=0&&rect.xMax<=Screen.width&&rect.yMin>=0&&rect.yMax<=Screen.height,"panel inside actual window "+size);Check(Click(col.Find("CollapseStack").GetComponent<UnityEngine.UI.Button>()),"hide actual hit "+size);yield return Settle();Check(Click(col.Find("CollapseStack").GetComponent<UnityEngine.UI.Button>()),"restore actual hit "+size);yield return Settle(.6f);ScreenCapture.CaptureScreenshot(W+"stack-reference-"+size.x+"x"+size.y+".png");yield return new WaitForEndOfFrame();
 }
 Restore();yield return null;while(!GamePreferences.Ready)yield return null;ui.Present(null,1,false,null,null,"");yield return null;ui.Present(Sample(),1,false,null,null,"副本 · 只读布局预览");yield return Settle(.7f);ScreenCapture.CaptureScreenshot(W+"stack-reference-final.png");yield return new WaitForEndOfFrame();Save("COMPLETE");
}
System.Collections.IEnumerator Guard(){var it=Run();for(int n=0;n<100000;n++){bool next=false;object value=null;try{next=it.MoveNext();if(next)value=it.Current;}catch(Exception e){failed++;results.Add(new{exception=e.ToString()});Restore();Save("ERROR");yield break;}if(!next)break;yield return value;}}
Save("STARTING");ui.StartCoroutine(Guard());return "Reference stack style and current ordinal checks started";
